-- Enable RLS on portal-facing tables
ALTER TABLE portal_users ENABLE ROW LEVEL SECURITY;
ALTER TABLE centre_agents ENABLE ROW LEVEL SECURITY;
ALTER TABLE centres ENABLE ROW LEVEL SECURITY;
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE call_attempts ENABLE ROW LEVEL SECURITY;
ALTER TABLE call_analytics ENABLE ROW LEVEL SECURITY;

-- portal_users: users can read their own row
CREATE POLICY "portal_users_select_own" ON portal_users
  FOR SELECT USING (id = auth.uid());

-- centre_agents: users can read agents for their centre
CREATE POLICY "centre_agents_select_own" ON centre_agents
  FOR SELECT USING (
    centre_id IN (SELECT centre_id FROM portal_users WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM portal_users WHERE id = auth.uid() AND role = 'admin')
  );

-- centres: users can read their own centre
CREATE POLICY "centres_select_own" ON centres
  FOR SELECT USING (
    id IN (SELECT centre_id FROM portal_users WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM portal_users WHERE id = auth.uid() AND role = 'admin')
  );

-- leads: users can read their centre's leads
CREATE POLICY "leads_select_own_centre" ON leads
  FOR SELECT USING (
    centre_id IN (SELECT centre_id FROM portal_users WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM portal_users WHERE id = auth.uid() AND role = 'admin')
  );

-- call_attempts: users can read their centre's call attempts
CREATE POLICY "call_attempts_select_own_centre" ON call_attempts
  FOR SELECT USING (
    centre_id IN (SELECT centre_id FROM portal_users WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM portal_users WHERE id = auth.uid() AND role = 'admin')
  );

-- call_analytics: users can read their centre's analytics
CREATE POLICY "call_analytics_select_own_centre" ON call_analytics
  FOR SELECT USING (
    centre_id IN (SELECT centre_id FROM portal_users WHERE id = auth.uid())
    OR EXISTS (SELECT 1 FROM portal_users WHERE id = auth.uid() AND role = 'admin')
  );

