import { createClient, type SupabaseClient } from '@supabase/supabase-js';

const SUPABASE_URL = process.env.SUPABASE_URL!;
const SUPABASE_SERVICE_KEY = process.env.SUPABASE_SERVICE_KEY!;
const SUPABASE_ANON_KEY = process.env.SUPABASE_ANON_KEY!;

// Service client: bypasses RLS, used for admin operations and webhooks
export const serviceClient: SupabaseClient = createClient(SUPABASE_URL, SUPABASE_SERVICE_KEY);

// Create a per-request client using the user's JWT — enforces RLS
export function createUserClient(accessToken: string): SupabaseClient {
  return createClient(SUPABASE_URL, SUPABASE_ANON_KEY, {
    global: {
      headers: { Authorization: `Bearer ${accessToken}` },
    },
  });
}

// Auth client for server-side sign-in (uses anon key)
export const authClient: SupabaseClient = createClient(SUPABASE_URL, SUPABASE_ANON_KEY);

import type { Context, Next } from 'hono';
import { serviceClient } from './supabase';
import type { PortalUser, Centre, CentreAgent, AuthContext } from './types';

// Hono middleware: validates JWT, attaches user + centre + agents to context
export async function authMiddleware(c: Context, next: Next) {
  const authHeader = c.req.header('Authorization');
  if (!authHeader?.startsWith('Bearer ')) {
    return c.json({ error: 'Missing or invalid Authorization header' }, 401);
  }

  const token = authHeader.slice(7);

  // Verify the JWT with Supabase Auth
  const { data: { user }, error: authError } = await serviceClient.auth.getUser(token);
  if (authError || !user) {
    return c.json({ error: 'Invalid or expired token' }, 401);
  }

  // Look up the portal user
  const { data: portalUser, error: puError } = await serviceClient
    .from('portal_users')
    .select('*')
    .eq('id', user.id)
    .single();

  if (puError || !portalUser) {
    return c.json({ error: 'No portal access configured for this account' }, 403);
  }

  // Look up the centre
  const { data: centre, error: centreError } = await serviceClient
    .from('centres')
    .select('id, location_name, timezone, timezone_display, twilio_number, calling_enabled')
    .eq('id', portalUser.centre_id)
    .single();

  if (centreError || !centre) {
    return c.json({ error: 'Centre not found' }, 404);
  }

  // Look up the agents for this centre
  const { data: agents } = await serviceClient
    .from('centre_agents')
    .select('*')
    .eq('centre_id', portalUser.centre_id);

  // Attach to context
  const authContext: AuthContext = {
    user: portalUser as PortalUser,
    centre: centre as Centre,
    agents: (agents || []) as CentreAgent[],
  };

  c.set('auth', authContext);
  c.set('token', token);
  await next();
}

// Helper to require admin role
export async function adminMiddleware(c: Context, next: Next) {
  const auth = c.get('auth') as AuthContext;
  if (auth.user.role !== 'admin') {
    return c.json({ error: 'Admin access required' }, 403);
  }
  await next();
}

// Helper to extract auth context from Hono context
export function getAuth(c: Context): AuthContext {
  return c.get('auth') as AuthContext;
}

import { Hono } from 'hono';
import { authClient, serviceClient } from '../lib/supabase';
import { authMiddleware, getAuth } from '../lib/auth-middleware';

const auth = new Hono();

// POST /api/auth/login — email/password sign-in
auth.post('/login', async (c) => {
  const { email, password } = await c.req.json<{ email: string; password: string }>();

  if (!email || !password) {
    return c.json({ error: 'Email and password are required' }, 400);
  }

  const { data, error } = await authClient.auth.signInWithPassword({ email, password });
  if (error) {
    return c.json({ error: 'Invalid credentials' }, 401);
  }

  // Verify they have a portal_users row
  const { data: portalUser } = await serviceClient
    .from('portal_users')
    .select('*, centres(id, location_name)')
    .eq('id', data.user.id)
    .single();

  if (!portalUser) {
    return c.json({ error: 'No portal access configured for this account' }, 403);
  }

  return c.json({
    access_token: data.session.access_token,
    refresh_token: data.session.refresh_token,
    expires_at: data.session.expires_at,
    user: {
      id: portalUser.id,
      email: portalUser.email,
      full_name: portalUser.full_name,
      role: portalUser.role,
      centre_id: portalUser.centre_id,
      centre_name: portalUser.centres?.location_name,
    },
  });
});

// POST /api/auth/refresh — refresh access token
auth.post('/refresh', async (c) => {
  const { refresh_token } = await c.req.json<{ refresh_token: string }>();

  if (!refresh_token) {
    return c.json({ error: 'Refresh token is required' }, 400);
  }

  const { data, error } = await authClient.auth.refreshSession({ refresh_token });
  if (error || !data.session) {
    return c.json({ error: 'Unable to refresh session' }, 401);
  }

  return c.json({
    access_token: data.session.access_token,
    refresh_token: data.session.refresh_token,
    expires_at: data.session.expires_at,
  });
});

// GET /api/auth/session — get current user + centre info
auth.get('/session', authMiddleware, async (c) => {
  const { user, centre, agents } = getAuth(c);

  return c.json({
    user: {
      id: user.id,
      email: user.email,
      full_name: user.full_name,
      role: user.role,
      centre_id: user.centre_id,
    },
    centre: {
      id: centre.id,
      location_name: centre.location_name,
      timezone: centre.timezone,
    },
    agents: agents.map((a) => ({
      retell_agent_id: a.retell_agent_id,
      agent_type: a.agent_type,
      label: a.label,
    })),
  });
});

export default auth;

import type { RetellCall, CallListItem, CallDetail, TranscriptUtterance, CentreAgent } from './types';

const RETELL_API_KEY = process.env.RETELL_API_KEY!;
const RETELL_BASE = 'https://api.retellai.com/v2';

async function retellFetch(path: string, options?: RequestInit): Promise<Response> {
  return fetch(`${RETELL_BASE}${path}`, {
    ...options,
    headers: {
      'Authorization': `Bearer ${RETELL_API_KEY}`,
      'Content-Type': 'application/json',
      ...options?.headers,
    },
  });
}

// Fetch calls for one or more agent IDs
export async function fetchCallsForAgents(
  agents: CentreAgent[],
  options: { limit?: number; beforeTimestamp?: number; afterTimestamp?: number } = {}
): Promise<CallListItem[]> {
  const limit = options.limit || 50;
  const allCalls: CallListItem[] = [];

  // Build agent lookup for labeling
  const agentMap = new Map(agents.map((a) => [a.retell_agent_id, a]));

  // Fetch calls per agent and merge
  const fetches = agents.map(async (agent) => {
    const body: Record<string, unknown> = {
      filter_criteria: {
        agent_id: [agent.retell_agent_id],
      },
      limit,
      sort_order: 'descending',
    };

    const res = await retellFetch('/list-calls', {
      method: 'POST',
      body: JSON.stringify(body),
    });

    if (!res.ok) {
      console.error(`Retell list-calls failed for ${agent.retell_agent_id}: ${res.status}`);
      return [];
    }

    const calls: RetellCall[] = await res.json();
    return calls.map((call) => transformCall(call, agentMap));
  });

  const results = await Promise.all(fetches);
  for (const calls of results) {
    allCalls.push(...calls);
  }

  // Sort by start time descending and limit
  allCalls.sort((a, b) => new Date(b.started_at).getTime() - new Date(a.started_at).getTime());
  return allCalls.slice(0, limit);
}

// Fetch a single call's full detail
export async function fetchCallDetail(callId: string): Promise<RetellCall | null> {
  const res = await retellFetch(`/get-call/${callId}`);
  if (!res.ok) {
    console.error(`Retell get-call failed for ${callId}: ${res.status}`);
    return null;
  }
  return res.json();
}

// Transform Retell API response to portal-friendly shape
function transformCall(call: RetellCall, agentMap: Map<string, CentreAgent>): CallListItem {
  const agent = agentMap.get(call.agent_id);
  const analysis = call.call_analysis;

  return {
    call_id: call.call_id,
    direction: call.direction || 'outbound',
    agent_type: agent?.agent_type || 'outbound',
    agent_label: agent?.label || 'Unknown Agent',
    from_number: call.from_number,
    to_number: call.to_number,
    duration_seconds: Math.round((call.duration_ms || 0) / 1000),
    started_at: call.start_timestamp
      ? new Date(call.start_timestamp).toISOString()
      : '',
    outcome: extractOutcome(analysis),
    sentiment: analysis?.user_sentiment || 'unknown',
    summary: analysis?.call_summary || '',
    in_voicemail: analysis?.in_voicemail || false,
  };
}

function extractOutcome(analysis?: RetellCall['call_analysis']): string {
  if (!analysis) return 'unknown';
  if (analysis.in_voicemail) return 'voicemail';

  const custom = analysis.custom_analysis_data as Record<string, string> | undefined;
  if (custom?.appointment_booked === 'true' || custom?.appointment_booked === 'yes') return 'booked';
  if (custom?.callback_requested === 'true') return 'callback';
  if (custom?.email_permission === 'true') return 'interested';
  if (analysis.call_successful === false) return 'not_interested';

  return 'completed';
}

// Transform transcript object to simplified utterances
export function simplifyTranscript(transcriptObject: TranscriptUtterance[] | undefined): TranscriptUtterance[] {
  if (!transcriptObject) return [];
  return transcriptObject.map(({ role, content }) => ({ role, content }));
}

import { Hono } from 'hono';
import { authMiddleware, getAuth } from '../lib/auth-middleware';
import { fetchCallsForAgents, fetchCallDetail, simplifyTranscript } from '../lib/retell';

const calls = new Hono();

calls.use('*', authMiddleware);

// GET /api/calls — list calls for user's centre
calls.get('/', async (c) => {
  const { agents } = getAuth(c);
  const limit = parseInt(c.req.query('limit') || '50');

  if (agents.length === 0) {
    return c.json([]);
  }

  const callList = await fetchCallsForAgents(agents, { limit });
  return c.json(callList);
});

// GET /api/calls/:callId — full call detail
calls.get('/:callId', async (c) => {
  const callId = c.req.param('callId');
  const { agents } = getAuth(c);

  const call = await fetchCallDetail(callId);
  if (!call) {
    return c.json({ error: 'Call not found' }, 404);
  }

  // Security: verify this call belongs to one of the user's centre agents
  const agentIds = new Set(agents.map((a) => a.retell_agent_id));
  if (!agentIds.has(call.agent_id)) {
    return c.json({ error: 'Access denied' }, 403);
  }

  return c.json({
    call_id: call.call_id,
    direction: call.direction || 'outbound',
    from_number: call.from_number,
    to_number: call.to_number,
    duration_seconds: Math.round((call.duration_ms || 0) / 1000),
    started_at: call.start_timestamp
      ? new Date(call.start_timestamp).toISOString()
      : '',
    recording_url: call.recording_url || null,
    transcript: simplifyTranscript(call.transcript_object),
    analysis: call.call_analysis || {},
    disconnection_reason: call.disconnection_reason,
  });
});

export default calls;

