import React, { useState, type FormEvent } from 'react';
import { createRoot } from 'react-dom/client';
import '../styles/index.css';

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const res = await fetch('/api/auth/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || 'Login failed');
        return;
      }

      // Store tokens and user info
      localStorage.setItem('tf_access_token', data.access_token);
      localStorage.setItem('tf_refresh_token', data.refresh_token);
      localStorage.setItem('tf_user', JSON.stringify(data.user));

      // Redirect to dashboard
      window.location.href = '/dashboard';
    } catch {
      setError('Network error. Please try again.');
    } finally {
      setLoading(false);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center px-4" style={{ background: 'var(--tf-navy)' }}>
      <div className="w-full max-w-sm">
        {/* Logo */}
        <div className="text-center mb-8">
          <h1 className="text-3xl font-bold text-white tracking-tight">
            <span style={{ color: 'var(--tf-blue)' }}>Tour</span>Force
          </h1>
          <p className="text-sm text-gray-400 mt-1">Voice AI Portal</p>
        </div>

        {/* Login form */}
        <form onSubmit={handleSubmit} className="rounded-xl p-6 space-y-4" style={{ background: 'var(--tf-navy-light)', border: '1px solid var(--tf-border)' }}>
          <div>
            <label className="block text-sm text-gray-400 mb-1">Email</label>
            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              autoFocus
              className="w-full px-3 py-2 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:ring-2"
              style={{ background: 'var(--tf-navy)', border: '1px solid var(--tf-border)', focusRingColor: 'var(--tf-blue)' }}
              placeholder="you@example.com"
            />
          </div>

          <div>
            <label className="block text-sm text-gray-400 mb-1">Password</label>
            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
              className="w-full px-3 py-2 rounded-lg text-white placeholder-gray-500 focus:outline-none focus:ring-2"
              style={{ background: 'var(--tf-navy)', border: '1px solid var(--tf-border)' }}
              placeholder="Enter your password"
            />
          </div>

          {error && (
            <div className="text-red-400 text-sm bg-red-900/20 px-3 py-2 rounded-lg">
              {error}
            </div>
          )}

          <button
            type="submit"
            disabled={loading}
            className="w-full py-2.5 rounded-lg font-medium text-white transition-colors disabled:opacity-50"
            style={{ background: loading ? '#4b5563' : 'var(--tf-blue)' }}
          >
            {loading ? 'Signing in...' : 'Sign In'}
          </button>
        </form>

        <p className="text-center text-xs text-gray-500 mt-6">
          Powered by TourForce AI
        </p>
      </div>
    </div>
  );
}

createRoot(document.getElementById('root')!).render(<Login />);

import React, { useState, useEffect } from 'react';
import { createRoot } from 'react-dom/client';
import '../styles/index.css';
import Layout from './Layout';
import CallLog from './CallLog';
import CallDetailView from './CallDetail';
import Analytics from './Analytics';
import Billing from './Billing';

type Route = 'calls' | 'call-detail' | 'analytics' | 'billing' | 'admin';

interface UserInfo {
  id: string;
  email: string;
  full_name: string | null;
  role: string;
  centre_id: string;
  centre_name: string;
}

function App() {
  const [route, setRoute] = useState<Route>('calls');
  const [callId, setCallId] = useState<string | null>(null);
  const [user, setUser] = useState<UserInfo | null>(null);

  // Check auth on mount
  useEffect(() => {
    const token = localStorage.getItem('tf_access_token');
    const stored = localStorage.getItem('tf_user');

    if (!token || !stored) {
      window.location.href = '/';
      return;
    }

    try {
      setUser(JSON.parse(stored));
    } catch {
      window.location.href = '/';
    }
  }, []);

  // Hash-based routing
  useEffect(() => {
    function handleHash() {
      const hash = window.location.hash.slice(1) || '/calls';
      if (hash.startsWith('/calls/')) {
        setRoute('call-detail');
        setCallId(hash.slice(7));
      } else if (hash === '/calls') {
        setRoute('calls');
        setCallId(null);
      } else if (hash === '/analytics') {
        setRoute('analytics');
      } else if (hash === '/billing') {
        setRoute('billing');
      } else if (hash === '/admin') {
        setRoute('admin');
      } else {
        setRoute('calls');
      }
    }

    handleHash();
    window.addEventListener('hashchange', handleHash);
    return () => window.removeEventListener('hashchange', handleHash);
  }, []);

  function handleLogout() {
    localStorage.removeItem('tf_access_token');
    localStorage.removeItem('tf_refresh_token');
    localStorage.removeItem('tf_user');
    window.location.href = '/';
  }

  if (!user) {
    return (
      <div className="min-h-screen flex items-center justify-center">
        <div className="text-gray-400">Loading...</div>
      </div>
    );
  }

  function renderContent() {
    switch (route) {
      case 'calls':
        return <CallLog />;
      case 'call-detail':
        return callId ? <CallDetailView callId={callId} /> : <CallLog />;
      case 'analytics':
        return <Analytics />;
      case 'billing':
        return <Billing />;
      default:
        return <CallLog />;
    }
  }

  return (
    <Layout user={user} currentRoute={route} onLogout={handleLogout}>
      {renderContent()}
    </Layout>
  );
}

createRoot(document.getElementById('root')!).render(<App />);

