export default function AudioPlayer({ url }: Props) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const [playing, setPlaying] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);

  function togglePlay() {
    const audio = audioRef.current;
    if (!audio) return;
    if (playing) {
      audio.pause();
    } else {
      audio.play();
    }
    setPlaying(!playing);
  }

  function handleTimeUpdate() {
    if (audioRef.current) {
      setCurrentTime(audioRef.current.currentTime);
    }
  }

  function handleLoadedMetadata() {
    if (audioRef.current) {
      setDuration(audioRef.current.duration);
    }
  }

  function handleSeek(e: React.MouseEvent<HTMLDivElement>) {
    const audio = audioRef.current;
    if (!audio || !duration) return;
    const rect = e.currentTarget.getBoundingClientRect();
    const pct = (e.clientX - rect.left) / rect.width;
    audio.currentTime = pct * duration;
  }

  function formatTime(s: number): string {
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60);
    return `${m}:${sec.toString().padStart(2, '0')}`;
  }

  const progress = duration > 0 ? (currentTime / duration) * 100 : 0;

  return (
    <div
      className="flex items-center gap-3 p-3 rounded-xl"
      style={{ background: 'var(--tf-navy-light)', border: '1px solid var(--tf-border)' }}
    >
      <audio
        ref={audioRef}
        src={url}
        onTimeUpdate={handleTimeUpdate}
        onLoadedMetadata={handleLoadedMetadata}
        onEnded={() => setPlaying(false)}
        preload="metadata"
      />

      {/* Play/Pause */}
      <button
        onClick={togglePlay}
        className="w-9 h-9 flex items-center justify-center rounded-full text-white shrink-0 transition-colors"
        style={{ background: 'var(--tf-blue)' }}
      >
        {playing ? '\u275A\u275A' : '\u25B6'}
      </button>

      {/* Time */}
      <span className="text-xs text-gray-400 w-10 text-right font-mono">
        {formatTime(currentTime)}
      </span>

      {/* Progress bar */}
      <div
        className="flex-1 h-2 rounded-full cursor-pointer"
        style={{ background: 'var(--tf-navy)' }}
        onClick={handleSeek}
      >
        <div
          className="h-full rounded-full transition-all"
          style={{ width: `${progress}%`, background: 'var(--tf-blue)' }}
        />
      </div>

      {/* Duration */}
      <span className="text-xs text-gray-400 w-10 font-mono">
        {formatTime(duration)}
      </span>
    </div>
  );
}

